/** A computed field. (03 §4.4; 12 §3.4) */
export interface FieldNode {
  type: "field";
  attrs?: FieldAttrs;
  marks?: CdmMark[];
}

export interface CitationAttrs {
  /** The cited sources in order, each with an optional prefix, suffix, locator and locator label (I4). Default: null. */
  items?: Array<{ source: string; prefix?: string; suffix?: string; locator?: string; label?: "act" | "appendix" | "article-locator" | "book" | "canon" | "chapter" | "column" | "elocation" | "equation" | "figure" | "folio" | "issue" | "line" | "note" | "opus" | "page" | "paragraph" | "part" | "rule" | "scene" | "section" | "sub-verbo" | "supplement" | "table" | "timestamp" | "title-locator" | "verse" | "version" | "volume" }> | null;
  /** `narrative` puts the authors in the text; `suppressAuthor` leaves them out. Default: "normal". */
  mode?: "normal" | "narrative" | "suppressAuthor";
  /** Last generated text, for consumers that cannot generate it. Default: null. */
  cached?: string | null;
  /** Attributes and child elements of the original Word element that the model does not represent, or a reference to a shared tree in `preserved_def` (ADR 0017, spike S11). Default: null. */
  preserved?: PreservedElementBody | PreservedTreeRef | null;
  /** The fragment of the imported file this atom came from, and the SHA-256 of its modelled attributes at import (spike S11). Default: null. */
  origin?: { fragment: string; hash: string } | null;
  /** Additive attributes under namespaced keys; every reader preserves it unchanged (03 §11.2). Default: {}. */
  ext?: { [key: string]: JsonValue };
}

/** A citation of one or more sources; the text is generated at layout and export time from the citation style. (03 §4.4; CDM-052) */
export interface CitationNode {
  type: "citation";
  attrs?: CitationAttrs;
  marks?: CdmMark[];
}

export interface AnchorAttrs {
  /** Node identifier; never changes once set (I2). Default: null. */
  id?: string | null;
  /** Bookmark name; unique in the document. Default: null. */
  name?: string | null;
  /** The fragment of the imported file this atom came from, and the SHA-256 of its modelled attributes at import (spike S11). Default: null. */
  origin?: { fragment: string; hash: string } | null;
  /** Additive attributes under namespaced keys; every reader preserves it unchanged (03 §11.2). Default: {}. */
  ext?: { [key: string]: JsonValue };
}

/** A zero-width bookmark. (03 §4.4) */
export interface AnchorNode {
  type: "anchor";
  attrs?: AnchorAttrs;
  marks?: CdmMark[];
}

export interface FormFieldAttrs {
  /** Node identifier; never changes once set (I2). Default: null. */
  id?: string | null;
  /** Data label, unique in the document (I13). Default: null. */
  key?: string | null;
  /** Field kind. The kind `attachment` is reserved and refused in version 1 (12 §3.2). Default: "text". */
  kind?: "text" | "number" | "date" | "checkbox" | "choice" | "signature" | "initials" | "dateSigned" | "formula";
  /** Accessible name and summary text. Default: null. */
  label?: string | null;
  /** Role placeholder that fills it, or null for a field only authors set (I13). Default: null. */
  assignee?: string | null;
  /** Static required flag; rules can also require a field. Default: false. */
  required?: boolean;
  /** Static read-only flag; rules can also disable a field. Default: false. */
  readOnly?: boolean;
  /** Current value, typed by kind; null means empty (12 §3.3; I15). Signature, initials, date-signed and formula values are set only by the server (P8). Default: null. */
  value?: JsonValue | null;
  /** Default value, typed like `value`. Default: null. */
  default?: JsonValue | null;
  /** Placeholder text. Default: null. */
  placeholder?: string | null;
  /** Choices of a `choice` field; option identifiers are unique within the field. Default: null. */
  options?: Array<{ id: string; label: string }> | null;
  /** Display format: decimals, prefix, suffix, date pattern. Default: null. */
  format?: { decimals?: number; prefix?: string; suffix?: string; datePattern?: string } | null;
  /** Static validation: decimal bounds, length bounds in Unicode code points, a restricted pattern (12 §5.2) and a preset. Default: null. */
  validation?: { min?: string; max?: string; minLength?: number; maxLength?: number; pattern?: string; preset?: "email" | "phone" | "postcode" } | null;
  /** Fixed width in twips, so filling moves no line break. Default: null. */
  width?: number | null;
  /** When true, the value is readable only by the principals of the read rule (ADR 0019, proposed; FRW-088): every other reader gets the redaction marker in place of `value` and `default`. Default: false. */
  sensitive?: boolean;
  /** Additive attributes under namespaced keys; every reader preserves it unchanged (03 §11.2). Default: {}. */
  ext?: { [key: string]: JsonValue };
}

/** A fillable field assigned to a role placeholder; not allowed in headers, footers or footnotes (I10). Feature `fields`. (12 §3.2) */
export interface FormFieldNode {
  type: "form_field";
  attrs?: FormFieldAttrs;
  marks?: CdmMark[];
}

export interface ExtensionInlineAttrs {
  /** Extension name. Default: null. */
  extension?: string | null;
  /** Extension data, at most 4 KiB (CDM-002); never interpreted by the model. Default: null. */
  payload?: JsonValue | null;
  /** Fallback text; required in a stored document. Default: null. */
  fallbackText?: string | null;
  /** Additive attributes under namespaced keys; every reader preserves it unchanged (03 §11.2). Default: {}. */
  ext?: { [key: string]: JsonValue };
}

/** A host-registered inline atom with a fallback text (I12). Feature `extensions`. (03 §4.4) */
export interface ExtensionInlineNode {
  type: "extension_inline";
  attrs?: ExtensionInlineAttrs;
  marks?: CdmMark[];
}

export interface PreservedInlineAttrs {
  /** Kind of content, for example "text box". Default: null. */
  label?: string | null;
  /** Asset holding the original XML and its parts; or null when `tree` holds a small marker. Default: null. */
  fragment?: string | null;
  /** The original element of a small marker without relationships, such as a bookmark Word alone uses (spike S11). Default: null. */
  tree?: PreservedElementBody | PreservedTreeRef | null;
  /** Fallback picture. Default: null. */
  fallbackAsset?: string | null;
  /** Fallback text. Default: null. */
  fallbackText?: string | null;
  /** Display width in twips. Default: null. */
  width?: number | null;
  /** Display height in twips. Default: null. */
  height?: number | null;
  /** Additive attributes under namespaced keys; every reader preserves it unchanged (03 §11.2). Default: {}. */
  ext?: { [key: string]: JsonValue };
}

/** Inline content from an imported file that the model cannot represent; changed only as a whole. It holds a fragment asset, or for a small marker without relationships an element tree (spike S11). Feature `preserve`. (03 §4.6; ADR 0017) */
export interface PreservedInlineNode {
  type: "preserved_inline";
  attrs?: PreservedInlineAttrs;
  marks?: CdmMark[];
}

export type CdmNode = DocNode | DefsNode | SettingsNode | StyleDefNode | NumberingDefNode | PageSetupNode | RoleDefNode | RuleDefNode | SourceDefNode | PreservedDefNode | StoryNode | BodyNode | RegionNode | SectionBreakNode | ParagraphNode | TableNode | TableRowNode | TableCellNode | FigureNode | CaptionNode | EquationBlockNode | TocNode | BibliographyNode | ExtensionBlockNode | PreservedBlockNode | TextNode | ImageNode | BreakNode | TabNode | EquationNode | FootnoteNode | FieldNode | CitationNode | AnchorNode | FormFieldNode | ExtensionInlineNode | PreservedInlineNode;

export type BlockNode = ParagraphNode | TableNode | FigureNode | EquationBlockNode | TocNode | BibliographyNode | ExtensionBlockNode | PreservedBlockNode;
export type InlineNode = TextNode | ImageNode | BreakNode | TabNode | EquationNode | FootnoteNode | FieldNode | CitationNode | AnchorNode | FormFieldNode | ExtensionInlineNode | PreservedInlineNode;

/** A CDM document as stored and transferred (03 §2). */
export interface CdmEnvelope {
  cdm: 1;
  requires: CdmFeature[];
  doc: DocNode;
}

// Projections (ADR 0019): nodes that only a reader's projection contains, never a stored document.

export interface HiddenRegionAttrs {
  /** Identifier of the hidden region. Default: null. */
  id?: string | null;
  /** Title of the hidden region, or null when the title is hidden too. Default: null. */
  title?: string | null;
}

/** Placeholder for a region the reader may not see: a block atom in the body, selectable whole, with no position inside it. Only in projections. In the content of `body` in a projection. (ADR 0019; CDM-053) */
export interface HiddenRegionNode {
  type: "hidden_region";
  attrs?: HiddenRegionAttrs;
}

export type ProjectionOnlyNode = HiddenRegionNode;
